// Temporary Phase 7 End-to-End API & Integration Smoke Test
const API_BASE = 'http://localhost:5123/api';
const FRONTEND_BASE = 'http://localhost:3000';

async function request(url, options = {}) {
  const res = await fetch(url, options);
  const text = await res.text();
  let json = null;
  try {
    json = JSON.parse(text);
  } catch {}
  return { status: res.status, ok: res.ok, json, text };
}

async function runSmokeTest() {
  console.log('--- Starting Phase 7 End-to-End Smoke Test ---');

  // 1. Verify Frontend Health
  console.log('\n[1/6] Verifying Frontend Dev Server...');
  const feRes = await request(FRONTEND_BASE);
  if (!feRes.ok || !feRes.text.includes('<div id="root"></div>')) {
    throw new Error(`Frontend failed to respond properly: status ${feRes.status}`);
  }
  console.log('✓ Frontend server is responding with valid HTML root.');

  // 2. Citizen Registration & Service Request Creation
  console.log('\n[2/6] Testing Citizen Workflow...');
  const citizenEmail = `ayse.smoke.${Date.now()}@bursa.bel.tr`;
  const regRes = await request(`${API_BASE}/auth/register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      firstName: 'Ayşe',
      lastName: 'Demir',
      email: citizenEmail,
      phoneNumber: '5551234567',
      password: 'Password123!',
      confirmPassword: 'Password123!'
    })
  });
  if (!regRes.ok) throw new Error(`Citizen registration failed: ${regRes.text}`);
  console.log(`✓ Registered citizen: ${citizenEmail}`);

  const citizenToken = regRes.json.accessToken;
  const citizenAuthHeader = { 'Authorization': `Bearer ${citizenToken}`, 'Content-Type': 'application/json' };

  // Fetch categories lookup
  const catRes = await request(`${API_BASE}/categories`, { headers: citizenAuthHeader });
  if (!catRes.ok || !catRes.json || catRes.json.length === 0) {
    throw new Error(`Categories lookup failed: ${catRes.text}`);
  }
  const roadCategory = catRes.json.find(c => c.name.includes('Road')) || catRes.json[0];
  console.log(`✓ Fetched categories: found "${roadCategory.name}" (${roadCategory.id})`);

  // Create service request
  const createReqRes = await request(`${API_BASE}/service-requests`, {
    method: 'POST',
    headers: citizenAuthHeader,
    body: JSON.stringify({
      title: 'Heykel Meydanı Yol Çukuru',
      description: 'Ana cadde üzerinde araç trafiğini tehlikeye atan derin çukur oluşmuştur.',
      categoryId: roadCategory.id,
      addressText: 'Heykel Meydanı No:12 Osmangazi / Bursa',
      latitude: 40.1828,
      longitude: 29.0667
    })
  });
  if (!createReqRes.ok) throw new Error(`Create service request failed: ${createReqRes.text}`);
  const requestId = createReqRes.json.id;
  console.log(`✓ Created service request with ID: ${requestId}, status: ${createReqRes.json.status}`);

  // Fetch citizen requests list
  const citizenListRes = await request(`${API_BASE}/service-requests?pageNumber=1&pageSize=10`, { headers: citizenAuthHeader });
  if (!citizenListRes.ok || citizenListRes.json.items.length === 0) {
    throw new Error(`Citizen requests list query failed: ${citizenListRes.text}`);
  }
  console.log(`✓ Citizen my-requests query succeeded: ${citizenListRes.json.totalCount} request(s) found.`);

  // 3. Manager Review and Assignment
  console.log('\n[3/6] Testing Manager Workflow (Review & Assign)...');
  const mgrLoginRes = await request(`${API_BASE}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'manager@bursa.bel.tr', password: 'Demo12345!' })
  });
  if (!mgrLoginRes.ok) throw new Error(`Manager login failed: ${mgrLoginRes.text}`);
  const mgrToken = mgrLoginRes.json.accessToken;
  const mgrAuthHeader = { 'Authorization': `Bearer ${mgrToken}`, 'Content-Type': 'application/json' };
  console.log('✓ Manager logged in successfully.');

  // Manager details view
  const mgrDetailRes = await request(`${API_BASE}/manager/service-requests/${requestId}`, { headers: mgrAuthHeader });
  if (!mgrDetailRes.ok) throw new Error(`Manager get request detail failed: ${mgrDetailRes.text}`);
  console.log(`✓ Manager retrieved request detail (Current Status: ${mgrDetailRes.json.status}).`);

  // Manager start review
  const reviewRes = await request(`${API_BASE}/manager/service-requests/${requestId}/review`, {
    method: 'POST',
    headers: mgrAuthHeader
  });
  if (!reviewRes.ok) throw new Error(`Start review failed: ${reviewRes.text}`);
  console.log('✓ Manager moved request to Reviewing status.');

  // Manager get departments lookup
  const deptRes = await request(`${API_BASE}/departments`, { headers: mgrAuthHeader });
  if (!deptRes.ok || deptRes.json.length === 0) throw new Error(`Departments lookup failed: ${deptRes.text}`);
  const fenIsleri = deptRes.json.find(d => d.name.includes('Fen')) || deptRes.json[0];
  console.log(`✓ Manager fetched departments: selected "${fenIsleri.name}" (${fenIsleri.id})`);

  // Manager get department employees
  const empLookupRes = await request(`${API_BASE}/departments/${fenIsleri.id}/employees`, { headers: mgrAuthHeader });
  if (!empLookupRes.ok || empLookupRes.json.length === 0) throw new Error(`Department employees lookup failed: ${empLookupRes.text}`);
  const assignedEmp = empLookupRes.json[0];
  console.log(`✓ Manager fetched department employees: selected "${assignedEmp.fullName}" (${assignedEmp.id})`);

  // Manager assign request
  const assignRes = await request(`${API_BASE}/manager/service-requests/${requestId}/assign`, {
    method: 'POST',
    headers: mgrAuthHeader,
    body: JSON.stringify({
      departmentId: fenIsleri.id,
      assignedEmployeeId: assignedEmp.id,
      priority: 'High'
    })
  });
  if (!assignRes.ok) throw new Error(`Assign request failed: ${assignRes.text}`);
  console.log('✓ Manager assigned request to employee with High priority.');

  // 4. Employee Workflow
  console.log('\n[4/6] Testing Employee Workflow (Start & Resolve)...');
  const empLoginRes = await request(`${API_BASE}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: assignedEmp.email, password: 'Demo12345!' })
  });
  if (!empLoginRes.ok) throw new Error(`Employee login failed: ${empLoginRes.text}`);
  const empToken = empLoginRes.json.accessToken;
  const empAuthHeader = { 'Authorization': `Bearer ${empToken}`, 'Content-Type': 'application/json' };
  console.log(`✓ Employee (${assignedEmp.fullName}) logged in successfully.`);

  // Employee list
  const empListRes = await request(`${API_BASE}/employee/service-requests?pageNumber=1&pageSize=10`, { headers: empAuthHeader });
  if (!empListRes.ok || empListRes.json.items.length === 0) {
    throw new Error(`Employee requests list query failed: ${empListRes.text}`);
  }
  console.log(`✓ Employee found ${empListRes.json.totalCount} assigned task(s).`);

  // Employee start work
  const startWorkRes = await request(`${API_BASE}/employee/service-requests/${requestId}/start`, {
    method: 'POST',
    headers: empAuthHeader
  });
  if (!startWorkRes.ok) throw new Error(`Employee start work failed: ${startWorkRes.text}`);
  console.log('✓ Employee started work (Status: InProgress).');

  // Employee resolve request
  const resolveRes = await request(`${API_BASE}/employee/service-requests/${requestId}/resolve`, {
    method: 'POST',
    headers: empAuthHeader,
    body: JSON.stringify({
      resolutionNote: 'Çukur alan sıcak asfalt ile doldurulmuş ve silindir ile düzeltilmiştir.'
    })
  });
  if (!resolveRes.ok) throw new Error(`Employee resolve request failed: ${resolveRes.text}`);
  console.log('✓ Employee resolved request with resolution note (Status: Resolved).');

  // 5. Manager Close Workflow
  console.log('\n[5/6] Testing Manager Verification and Closure...');
  const closeRes = await request(`${API_BASE}/manager/service-requests/${requestId}/close`, {
    method: 'POST',
    headers: mgrAuthHeader,
    body: JSON.stringify({
      closureNote: 'Saha kontrolü yapıldı, asfaltlama tamamlandı ve onaylandı.'
    })
  });
  if (!closeRes.ok) throw new Error(`Manager close request failed: ${closeRes.text}`);
  console.log('✓ Manager closed request with closure note (Status: Closed).');

  // 6. Verify Complete Status History Timeline
  console.log('\n[6/6] Verifying Lifecycle Timeline & History...');
  const finalDetailRes = await request(`${API_BASE}/manager/service-requests/${requestId}`, { headers: mgrAuthHeader });
  if (!finalDetailRes.ok) throw new Error(`Get final request detail failed: ${finalDetailRes.text}`);

  const finalData = finalDetailRes.json;
  console.log(`✓ Final Status: ${finalData.status}`);
  console.log(`✓ Priority: ${finalData.priority}`);
  console.log(`✓ Assigned Department: ${finalData.departmentName}`);
  console.log(`✓ Assigned Employee: ${finalData.assignedEmployeeName}`);
  console.log(`✓ Resolution Note: ${finalData.resolutionNote}`);
  console.log(`✓ Status History (${finalData.statusHistory?.length || 0} transitions):`);
  for (const h of (finalData.statusHistory || [])) {
    console.log(`    - ${h.fromStatus ?? 'Initial'} -> ${h.toStatus} (Note: ${h.note ?? 'None'}) at ${h.changedAtUtc}`);
  }

  console.log('\n======================================================');
  console.log('🎉 ALL SMOKE TEST STEPS PASSED WITH 100% SUCCESS!');
  console.log('======================================================');
}

runSmokeTest().catch((err) => {
  console.error('\n❌ Smoke Test Failed:', err.message);
  process.exit(1);
});

