args.CodeContent:
server {
    listen 80;
    server_name localhost;

    # Root directory for static production bundle
    root /usr/share/nginx/html;
    index index.html;

    # Gzip compression
    gzip on;
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript;

    # Reverse proxy for backend API requests
    location /api/ {
        proxy_pass http://api:8080/api/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 30s;
        proxy_read_timeout 60s;
    }

    # Health check proxy (optional direct passthrough)
    location /health {
        proxy_pass http://api:8080/health;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
    }

    # SPA routing: fallback to index.html for React Router
    location / {
        try_files $uri $uri/ /index.html;
    }

    # Cache static assets
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
        expires 1y;
        add_header Cache-Control "public, max-age=31536000, immutable";
        try_files $uri =404;
    }
}

// Phase 8 Complete Docker & Persistence Smoke Test
const BASE_URL = 'http://localhost:3000';
const API_URL = `${BASE_URL}/api`;

async function request(url, options = {}) {
  const res = await fetch(url, options);
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch {}
  return { status: res.status, ok: res.ok, json, text };
}

async function runDockerSmokeTest() {
  console.log('========================================================');
  console.log('🚀 Phase 8: Docker Containerized Stack Smoke Test');
  console.log('========================================================\n');

  // 1. Health & Reverse Proxy Check
  console.log('[1/7] Testing Web Server and Reverse Proxy Health...');
  const healthRes = await request(`${BASE_URL}/health`);
  if (!healthRes.ok || !healthRes.text.includes('Healthy')) {
    throw new Error(`Health check failed: status ${healthRes.status}, body: ${healthRes.text}`);
  }
  console.log('✓ Health check passed (HTTP 200 Healthy via Nginx proxy).');

  // 2. React Router SPA direct refresh test
  console.log('\n[2/7] Testing React Router SPA Fallback routes...');
  const routes = ['/citizen/requests', '/manager/requests', '/employee/requests', '/login', '/register'];
  for (const r of routes) {
    const routeRes = await request(`${BASE_URL}${r}`);
    if (!routeRes.ok || !routeRes.text.includes('<div id="root"></div>')) {
      throw new Error(`SPA route ${r} failed with status ${routeRes.status}`);
    }
  }
  console.log(`✓ All ${routes.length} React Router deep routes loaded index.html fallback successfully (No 404s).`);

  // 3. Citizen Registration & Service Request Creation
  console.log('\n[3/7] Testing Citizen Flow via Docker Stack...');
  const citizenEmail = `ayse.docker.${Date.now()}@bursa.bel.tr`;
  const citizenPassword = 'Password123!';

  const regRes = await request(`${API_URL}/auth/register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      firstName: 'Ayşe',
      lastName: 'Demir',
      email: citizenEmail,
      phoneNumber: '5551234567',
      password: citizenPassword
    })
  });
  if (!regRes.ok) throw new Error(`Citizen registration failed: ${regRes.text}`);
  console.log(`✓ Citizen registered: ${citizenEmail} (ID: ${regRes.json.id})`);

  const citizenLoginRes = await request(`${API_URL}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: citizenEmail, password: citizenPassword })
  });
  if (!citizenLoginRes.ok) throw new Error(`Citizen login failed: ${citizenLoginRes.text}`);
  const citizenToken = citizenLoginRes.json.accessToken;
  const citizenHeaders = { 'Authorization': `Bearer ${citizenToken}`, 'Content-Type': 'application/json' };
  console.log('✓ Citizen logged in, received JWT.');

  // Fetch Categories
  const catRes = await request(`${API_URL}/categories`, { headers: citizenHeaders });
  if (!catRes.ok || !catRes.json || catRes.json.length === 0) {
    throw new Error(`Categories lookup failed: ${catRes.text}`);
  }
  const roadCat = catRes.json.find(c => c.name.includes('Road')) || catRes.json[0];
  console.log(`✓ Categories loaded: "${roadCat.name}" (${roadCat.id})`);

  // Create Request
  const createRes = await request(`${API_URL}/service-requests`, {
    method: 'POST',
    headers: citizenHeaders,
    body: JSON.stringify({
      title: 'Docker Test: Yol Çukuru Onarımı',
      description: 'Osmangazi Heykel Meydanı civarında çukur tespiti.',
      categoryId: roadCat.id,
      addressText: 'Heykel Meydanı No:12 Osmangazi / Bursa',
      latitude: 40.1828,
      longitude: 29.0667
    })
  });
  if (!createRes.ok) throw new Error(`Create service request failed: ${createRes.text}`);
  const createdRequestId = createRes.json.id;
  console.log(`✓ Created service request ID: ${createdRequestId} (Status: ${createRes.json.status})`);

  // 4. Manager Review and Assignment
  console.log('\n[4/7] Testing Manager Workflow (Review & Assign)...');
  const mgrLoginRes = await request(`${API_URL}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'manager@bursa.bel.tr', password: 'Demo12345!' })
  });
  if (!mgrLoginRes.ok) throw new Error(`Manager login failed: ${mgrLoginRes.text}`);
  const mgrToken = mgrLoginRes.json.accessToken;
  const mgrHeaders = { 'Authorization': `Bearer ${mgrToken}`, 'Content-Type': 'application/json' };

  // Start Review
  const reviewRes = await request(`${API_URL}/manager/service-requests/${createdRequestId}/review`, {
    method: 'POST',
    headers: mgrHeaders
  });
  if (!reviewRes.ok) throw new Error(`Review failed: ${reviewRes.text}`);
  console.log('✓ Manager started review (Status: Reviewing).');

  // Fetch departments & employees
  const deptRes = await request(`${API_URL}/departments`, { headers: mgrHeaders });
  const fenIsleri = deptRes.json.find(d => d.name.includes('Fen')) || deptRes.json[0];
  const empRes = await request(`${API_URL}/departments/${fenIsleri.id}/employees`, { headers: mgrHeaders });
  const assignedEmp = empRes.json[0];
  console.log(`✓ Manager selected Department: "${fenIsleri.name}", Employee: "${assignedEmp.fullName}"`);

  // Assign
  const assignRes = await request(`${API_URL}/manager/service-requests/${createdRequestId}/assign`, {
    method: 'POST',
    headers: mgrHeaders,
    body: JSON.stringify({
      departmentId: fenIsleri.id,
      employeeId: assignedEmp.id,
      priority: 'High'
    })
  });
  if (!assignRes.ok) throw new Error(`Assign failed: ${assignRes.text}`);
  console.log('✓ Manager assigned request to employee with High priority (Status: Assigned).');

  // 5. Employee Workflow
  console.log('\n[5/7] Testing Employee Workflow (Start & Resolve)...');
  const empLoginRes = await request(`${API_URL}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: assignedEmp.email, password: 'Demo12345!' })
  });
  if (!empLoginRes.ok) throw new Error(`Employee login failed: ${empLoginRes.text}`);
  const empHeaders = { 'Authorization': `Bearer ${empLoginRes.json.accessToken}`, 'Content-Type': 'application/json' };

  // Start Work
  const startWorkRes = await request(`${API_URL}/employee/service-requests/${createdRequestId}/start`, {
    method: 'POST',
    headers: empHeaders
  });
  if (!startWorkRes.ok) throw new Error(`Start work failed: ${startWorkRes.text}`);
  console.log('✓ Employee started work (Status: InProgress).');

  // Resolve
  const resolveRes = await request(`${API_URL}/employee/service-requests/${createdRequestId}/resolve`, {
    method: 'POST',
    headers: empHeaders,
    body: JSON.stringify({
      note: 'Docker test: Yol çukuru sıcak asfalt dökülerek düzeltildi.'
    })
  });
  if (!resolveRes.ok) throw new Error(`Resolve failed: ${resolveRes.text}`);
  console.log('✓ Employee marked request as Resolved with resolution note.');

  // 6. Manager Close Workflow
  console.log('\n[6/7] Testing Manager Close Workflow...');
  const closeRes = await request(`${API_URL}/manager/service-requests/${createdRequestId}/close`, {
    method: 'POST',
    headers: mgrHeaders,
    body: JSON.stringify({
      note: 'Docker test: Saha denetimi tamamlandı, işlem onaylandı.'
    })
  });
  if (!closeRes.ok) throw new Error(`Close failed: ${closeRes.text}`);
  console.log('✓ Manager closed request with closure note (Status: Closed).');

  // 7. Verify Final Record in SQL Server
  console.log('\n[7/7] Verifying Persisted State & Status History in SQL Server...');
  const detailRes = await request(`${API_URL}/manager/service-requests/${createdRequestId}`, { headers: mgrHeaders });
  if (!detailRes.ok) throw new Error(`Get detail failed: ${detailRes.text}`);

  const detail = detailRes.json;
  console.log(`✓ Request ID: ${detail.id}`);
  console.log(`✓ Final Status: ${detail.status}`);
  console.log(`✓ Priority: ${detail.priority}`);
  console.log(`✓ Total History Entries: ${detail.statusHistory?.length}`);

  console.log('\n========================================================');
  console.log('✅ ALL DOCKER CONTAINER STACK SMOKE TESTS PASSED (100%)');
  console.log('========================================================');

  // Return the created ID so we can test persistence across restarts
  return { requestId: createdRequestId, mgrToken };
}

runDockerSmokeTest().catch(err => {
  console.error('\n❌ Docker Smoke Test Failed:', err.message);
  process.exit(1);
});

// Verify data persistence after container restart
const BASE_URL = 'http://localhost:3000/api';

async function checkPersistence() {
  console.log('--- Checking Persistence After Restart ---');

  // 1. Manager Login
  const loginRes = await fetch(`${BASE_URL}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'manager@bursa.bel.tr', password: 'Demo12345!' })
  });
  if (!loginRes.ok) throw new Error('Manager login failed after restart');
  const { accessToken } = await loginRes.json();

  // 2. Fetch the existing request created before restart
  const reqRes = await fetch(`${BASE_URL}/manager/service-requests/362ba8f7-bf21-4fa0-a97f-4b421e2dd16f`, {
    headers: { 'Authorization': `Bearer ${accessToken}` }
  });
  if (!reqRes.ok) throw new Error(`Fetch request failed: status ${reqRes.status}`);
  const data = await reqRes.json();

  console.log('✓ Successfully retrieved pre-existing request after restart!');
  console.log(`✓ ID: ${data.id}`);
  console.log(`✓ Title: ${data.title}`);
  console.log(`✓ Status: ${data.status}`);
  console.log(`✓ Department: ${data.categoryName}`);
  console.log(`✓ Status History Count: ${data.statusHistory?.length}`);

  if (data.status !== 'Closed' || data.statusHistory?.length !== 5) {
    throw new Error('Data persistence mismatch!');
  }
  console.log('🎉 PERSISTENCE CHECK PASSED 100%!');
}

checkPersistence().catch(err => {
  console.error('❌ Persistence Check Failed:', err.message);
  process.exit(1);
});

