import http from 'http';

function request(options, data) {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, body: body ? JSON.parse(body) : null });
        } catch {
          resolve({ status: res.statusCode, body });
        }
      });
    });
    req.on('error', reject);
    if (data) req.write(JSON.stringify(data));
    req.end();
  });
}

async function runSmokeTest() {
  console.log('=== Starting PostgreSQL E2E Workflow Smoke Test ===');

  // 1. Health check
  const health = await request({ host: 'localhost', port: 3000, path: '/health', method: 'GET' });
  console.log('1. Health Check:', health.status, health.body);

  // 2. Register Citizen
  const citizenReg = await request(
    { host: 'localhost', port: 3000, path: '/api/auth/register', method: 'POST', headers: { 'Content-Type': 'application/json' } },
    { firstName: 'Zeynep', lastName: 'Kaya', email: `zeynep.pg.${Date.now()}@example.com`, password: 'Citizen12345!', phoneNumber: '5559876543' }
  );
  console.log('2. Citizen Registered:', citizenReg.status, citizenReg.body?.id, citizenReg.body?.email);

  // 3. Login Citizen
  const citizenLogin = await request(
    { host: 'localhost', port: 3000, path: '/api/auth/login', method: 'POST', headers: { 'Content-Type': 'application/json' } },
    { email: citizenReg.body.email, password: 'Citizen12345!' }
  );
  const citizenToken = citizenLogin.body.accessToken;
  console.log('3. Citizen Logged in:', citizenLogin.status, citizenLogin.body?.user?.role);

  // 4. Create Service Request
  const categories = await request({
    host: 'localhost', port: 3000, path: '/api/categories', method: 'GET',
    headers: { 'Authorization': `Bearer ${citizenToken}` }
  });
  const roadCatId = categories.body[0].id;

  const createReq = await request(
    { host: 'localhost', port: 3000, path: '/api/service-requests', method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${citizenToken}` } },
    { title: 'PG Test Asfalt Hasari', categoryId: roadCatId, description: 'Yolda derin cukur olustu.', addressText: 'Inegol Bursa', latitude: 40.08, longitude: 29.51 }
  );
  const reqId = createReq.body.id;
  console.log('4. Service Request Created:', createReq.status, 'ID:', reqId, 'Status:', createReq.body.status);

  // 5. Login Manager
  const mgrLogin = await request(
    { host: 'localhost', port: 3000, path: '/api/auth/login', method: 'POST', headers: { 'Content-Type': 'application/json' } },
    { email: 'manager@bursa.bel.tr', password: 'Demo12345!' }
  );
  const mgrToken = mgrLogin.body.accessToken;
  console.log('5. Manager Logged in:', mgrLogin.status);

  // 6. Review Request
  const review = await request({
    host: 'localhost', port: 3000, path: `/api/manager/service-requests/${reqId}/review`, method: 'POST',
    headers: { 'Authorization': `Bearer ${mgrToken}` }
  });
  console.log('6. Manager Reviewed:', review.status, 'Status:', review.body.status);

  // 7. Assign Request
  const assign = await request(
    { host: 'localhost', port: 3000, path: `/api/manager/service-requests/${reqId}/assign`, method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${mgrToken}` } },
    { departmentId: '10000000-0000-0000-0000-000000000001', employeeId: '30000000-0000-0000-0000-000000000002', priority: 'High' }
  );
  console.log('7. Manager Assigned:', assign.status, 'Status:', assign.body.status, 'Priority:', assign.body.priority);

  // 8. Login Employee
  const empLogin = await request(
    { host: 'localhost', port: 3000, path: '/api/auth/login', method: 'POST', headers: { 'Content-Type': 'application/json' } },
    { email: 'employee1@bursa.bel.tr', password: 'Demo12345!' }
  );
  const empToken = empLogin.body.accessToken;
  console.log('8. Employee Logged in:', empLogin.status);

  // 9. Start Work
  const startWork = await request({
    host: 'localhost', port: 3000, path: `/api/employee/service-requests/${reqId}/start`, method: 'POST',
    headers: { 'Authorization': `Bearer ${empToken}` }
  });
  console.log('9. Employee Started Work:', startWork.status, 'Status:', startWork.body.status);

  // 10. Resolve Request
  const resolve = await request(
    { host: 'localhost', port: 3000, path: `/api/employee/service-requests/${reqId}/resolve`, method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${empToken}` } },
    { resolutionNotes: 'Asfalt cukuru sicak karisimla dolduruldu ve sikistirildi.' }
  );
  console.log('10. Employee Resolved:', resolve.status, 'Status:', resolve.body.status);

  // 11. Close Request
  const close = await request(
    { host: 'localhost', port: 3000, path: `/api/manager/service-requests/${reqId}/close`, method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${mgrToken}` } },
