import http from 'http';

function request(options, data) {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, body: body ? JSON.parse(body) : null });
        } catch {
          resolve({ status: res.statusCode, body });
        }
      });
    });
    req.on('error', reject);
    if (data) req.write(JSON.stringify(data));
    req.end();
  });
}

async function verifyPersistence() {
  console.log('=== Checking PostgreSQL Persistence After Restart ===');
  const mgrLogin = await request(
    { host: 'localhost', port: 3000, path: '/api/auth/login', method: 'POST', headers: { 'Content-Type': 'application/json' } },
    { email: 'manager@bursa.bel.tr', password: 'Demo12345!' }
  );
  const mgrToken = mgrLogin.body.accessToken;
  console.log('Manager Logged In:', mgrLogin.status);

  const reqId = '934e95f8-8879-462c-a3f0-de32b9250122';
  const detail = await request({
    host: 'localhost', port: 3000, path: `/api/manager/service-requests/${reqId}`, method: 'GET',
    headers: { 'Authorization': `Bearer ${mgrToken}` }
  });
  console.log('Persisted Request Status:', detail.status, detail.body?.status, detail.body?.title);
  console.log('Persisted Status History Count:', detail.body?.statusHistory?.length);
  if (detail.body?.status === 'Closed' && detail.body?.statusHistory?.length === 5) {
    console.log('=== Persistence Verification PASSED ===');
  } else {
    throw new Error('Persistence verification failed');
  }
}

